# -*- coding: utf-8 -*-
"""دفعة المقالات 2ب — تحديث 8 مقالات من البيانات الموثقة (sources-log.md 30/9/2026)
Atomic patch: يفشل كله أو ينفع كله — بدون تعديل جزئي.
المصادر: أقسام استخراج المعاش + نقل ملكية السيارة + تأسيس الشركات + تسجيل الطلاب (EMIS)
+ التوفير البريدي + كارت العلاج المجاني/التأمين الصحي + تصديق الشهادات + الجنسية المصرية."""
import re, sys, shutil

PATH = "articles.html"
BAK = "articles.html.bak-batch2b"

UPDATES = {
    "إزاي تطلع المعاش؟":
        r"""<h3>📋 الخطوات</h3><p>1. قدّم طلب الصرف من محطة الصرف التابعة لسكنك (مكتب البريد أو البنك حسب المحافظة)</p><p>2. اطلع إخطار استحقاق المعاش من الهيئة القومية للتأمين الاجتماعي بعد مراجعة مدد الاشتراك</p><p>3. سجّل عنوانك ورقم موبايلك للتوصيل الإلكتروني أو الدفع بالماكينة</p><h3>⏰ المواعيد</h3><p>• سن المعاش القانوني بالقانون 148/2019</p><p>• المعاش المبكر من سن 55 بخصم 4.5% لكل سنة نقص ومؤهل بعد 300 شهر اشتراك</p><p>• أقصى أجر اشتراك 14,500 جنيه شهريًا</p><h3>💡 نصيحة</h3><p>• استعلام الموقف التأميني أونلاين من <a href=\"https://www.si.gov.eg\" target=\"_blank\">si.gov.eg</a> أو الخط الساخن 16163</p><p>• المعاش بيتصرف من أول الشهر التالي لاستحقاقه</p>""",
    "إزاي تنقل ملكية سيارة؟":
        r"""<h3>📋 الخطوات</h3><p>1. اتفق مع المشتري على السعر واطلب شهادة بيانات السيارة (فحص فني + حصر مخالفات من وحدة المرور)</p><p>2. امضوا عقد البيع وإقرار البيع من وحدة المرور</p><p>3. سدد رسوم النقل (فحص فني + نموذج 24 + إقرار بيع + لجان فحص إن وجدت)</p><p>4. استخرج رخصة جديدة باسم المشتري ولوحات جديدة</p><h3>💰 الرسوم</h3><p>• رسوم الفحص الفني ونموذج 24 حسب نوع السيارة</p><p>• لوحات معدنية جديدة ~350 جنيه</p><h3>⏰ مهم!</h3><p>• النقل لازم يتم في وحدة المرور المختصة قبل تحرير أي مخالفات</p><p>• المطلوب: البطاقتان + شهادة بيانات السيارة + شهادة المخالفات + عقد البيع وإقرار البيع</p>""",
    "إزاي تفتح مشروعك الخاص؟":
        r"""<h3>📋 الخطوات</h3><p>1. اختار شكل المشروع (شركة أشخاص أو أموال أو مكتب/منشأة فردية)</p><p>2. حجز الاسم وإعداد عقد التأسيس والموافقات الأمنية والبنكية (تقديم إلكتروني بالكامل عبر <a href=\"https://www.gafi.gov.eg\" target=\"_blank\">gafi.gov.eg</a>)</p><p>3. سجل الشركة في السجل التجاري واستخرج البطاقة الضريبية</p><h3>💰 التكاليف</h3><p>رسوم التأسيس والسجل التجاري حسب شكل الشركة ونشاطها</p><h3>⏰ مهم!</h3><p>• تأسيس الشركات تقديمه إلكتروني بالكامل عبر بوابة جهاز الاستثمار (GAFI)</p><p>• الموافقات المسبقة لبعض الأنشطة (استيراد/تصدير/صحة) قبل التسجيل</p>""",
    "إزاي تسجّل طفل في مدرسة حكومية؟":
        r"""<h3>📋 الخطوات</h3><p>1. التقديم من نظام EMIS (نظام管理 المعلومات التعليمية) عبر <a href=\"https://emis.gov.eg\" target=\"_blank\">emis.gov.eg</a> برقم قومي للطفل وللوالد</p><p>2. اختار المدرسة الحكومية حسب عنوان الإقامة الرسمي</p><p>3. ارفع المستندات إلكترونيًا أو سلّمها بالمدرسة</p><p>4. متابعة القبول من النظام</p><h3>📄 المستندات</h3><p>• شهادة ميلاد الطفل (رقم قومي)</p><p>• بطاقة الرقم القومي للوالد/الولي</p><p>• إثبات عنوان سكن (فاتورة مرافق أو عقد إيجار)</p><p>• 4 صور شخصية</p><h3>⏰ مهم!</h3><p>التقديم الإلزامي أونلاين لنقل وطلاب الصف الأول عبر نظام EMIS — والتقديم مجاني في المدارس الحكومية</p>""",
    "إزاي تفتح حساب توفير بريدي؟":
        r"""<h3>📋 الخطوات</h3><p>1. اختار نوع الحساب (توفير بريد مصر أو شهادات ادخارية) وروح لأقرب فرع بريد</p><p>2. املا نموذج فتح الحساب وسلّم صورة بطاقة الرقم القومي</p><p>3. ايدع المبلغ الأولانيات (حسب نوع الحساب)</p><h3>💰 المزايا</h3><p>• توفير يومي وصرف من أي فرع بريد على مستوى الجمهورية</p><p>• الشهادات الادخارية متاحة للأفراد والقاصرين برأس مال صغير</p><p>• استرداد الشهادات في أي وقت من أي مكتب بريد</p><h3>⏰ مهم!</h3><p>• الحساب بيقبل الإيداع والصرف من أي فرع بريد على مستوى الجمهورية</p><p>• فيه أنواع مختلفة من الشهادات حسب مدة العائد ورأس المال</p>""",
    "إزاي تطلع كارت علاج مجاني؟":
        r"""<h3>📋 الخطوات</h3><p>1. سجّل بيانات أسرتك التأمينية أونلاين من <a href=\"https://digital.gov.eg\" target=\"_blank\">بوابة مصر الرقمية</a> — اختار المحافظة حسب البطاقة واحفظ</p><p>2. بعد 48 ساعة روح لوحدة الرعاية الأولية لسداد الاشتراك واستلام الكارت برقم الملف العائلي</p><p>3. اعمل الفحص المبدئي وافتح الملف العائلي</p><h3>👥 مين بيسجل إزاي؟</h3><p>• غير الخاضعين للتأمينات: من مكتب خدمة العملاء لبيانات الدخل والسداد الذاتي</p><p>• الغير قادرين: الدولة بتسدد عنهم</p><h3>📍 المحافظات المتاحة</h3><p>• المرحلة الأولى: بورسعيد، الأقصر، الإسماعيلية، جنوب سيناء، السويس، أسوان</p><p>• المرحلة الثانية: دمياط، كفر الشيخ، المنيا، مطروح، شمال سيناء</p><h3>💡 المميزات</h3><p>تغطية من الولادة للوفاة + مساهمات رمزية على الأدوية والأشعة والتحاليل (والمعفيون منها: الغير قادرين وأصحاب الأمراض المزمنة والأورام)</p>""",
    "إزاي تستخرج شهادة مؤهل دراسي؟":
        r"""<h3>📋 الخطوات</h3><p>1. استخرج صورة رسمية من الشهادة: الجامعية من شئون الطلاب ← وكيل الكلية للتعليم ← أمين عام الجامعة</p><p>2. الثانوية والإعدادية من الإدارة التعليمية ← المديرية التعليمية ← سكرتير عام المحافظة</p><p>3. صدّق الشهادة من مكاتب تصديقات وزارة الخارجية (المكتب الرئيسي: مجمع التحرير)</p><h3>💰 الرسوم</h3><p>• تصديق غير تجاري (ومنه الشهادات الدراسية): 11 جنيه</p><p>• تصديق تجاري: 25 جنيه</p><h3>⏰ المدة</h3><p>• عادي: 3-5 أيام عمل</p><p>• فوري: نفس اليوم برسوم أعلى</p><h3>📄 المستندات</h3><p>• الشهادة الأصلية</p><p>• صورة بطاقة الرقم القومي سارية</p><p>• الترجمة المعتمدة لو مطلوبة للجهة الأجنبية</p><h3>💡 نصيحة</h3><p>لو الشهادة لجهة رسمية في دولة أجنبية: تصديق وزارة الخارجية + سفارة الدولة المعنية لو مشترطة</p>""",
    "إزاي تطلب الجنسية المصرية؟":
        r"""<h3>📋 الجهة المختصة</h3><p>وزارة الداخلية — مصلحة الجوازات والهجرة والجنسية هي الجهة الوحيدة المختصة بالجنسية المصرية إثباتًا وكسبًا واستردادًا</p><h3>📋 الخطوات</h3><p>1. قدّم طلبك من قسم الجنسية بمصلحة الجوازات أو إلكترونيًا عبر دليل خدمات الجوازات <a href=\"https://enationality.moi.gov.eg" target=\"_blank\">enationality.moi.gov.eg</a></p><p>2. سدد الرسوم وجمّع المستندات المطلوبة لمسارك (الميلاد من أب مصري، أو التجنيس، أو الاسترداد)</p><p>3. متابعة الطلب من البوابة الرسمية للجنسية المصرية <a href=\"https://egyptcitizenship.gov.eg" target=\"_blank\">egyptcitizenship.gov.eg</a></p><h3>💰 الرسوم</h3><p>• جدول رسوم شهادات الجوازات يبدأ من ~47 جنيه حسب نوع الشهادة والسن</p><p>• عاجل اختياري: 100 جنيه</p><p>• لو الشهادة لجهة قضائية: بصرح من المحكمة أو النيابة المختصة</p><h3>⏰ مهم!</h3><p>• شروط كل مسار (أحكام قانون 140/2019) بتحددها البوابة الرسمية — راجعها قبل التقديم</p>""",
}

src = open(PATH, encoding="utf-8").read()
shutil.copyfile(PATH, BAK)
count_before = src.count("title:'")
problems = []
for title, new_content in UPDATES.items():
    esc = re.escape(title)
    pattern = re.compile(r"(title:'" + esc + r"'.*?content:`)[^`]*(`)", re.DOTALL)
    if len(pattern.findall(src)) != 1:
        problems.append(title); continue
    src = pattern.sub(lambda m: m.group(1) + new_content + m.group(2), src, count=1)

if problems:
    open(PATH, "w", encoding="utf-8").write(open(BAK, encoding="utf-8").read())
    sys.exit("فشل التطابق لـ: " + ", ".join(problems) + " — تم التراجع")

if src.count("title:'") != count_before or src.count("content:`") != count_before:
    sys.exit("عدد المقالات اتغير! — لم يتم الحفظ")

open(PATH, "w", encoding="utf-8").write(src)
checks = ["148/2019", "300 شهر", "نموذج 24", "gafi.gov.eg", "EMIS", "على مستوى الجمهورية",
          "المكتب الرئيسي: مجمع التحرير", "11 جنيه", "egyptcitizenship.gov.eg"]
print("OK — تم تحديث 8 مقالات. عدد المقالات الكلي:", count_before)
for c in checks:
    print(("✓ " if c in src else "✗ مفقود ") + c)
